describe('Export Records to CSV', () => {
  beforeEach(() => {
    cy.visit('/records');
    cy.login('testuser@example.com', 'password123');
  });

  it('should export a list of records to CSV successfully', () => {
    cy.get('[data-testid="records-table"]').should('be.visible');
    cy.get('[data-testid="record-row"]').should('have.length.greaterThan', 0);

    cy.get('[data-testid="export-button"]').click();
    cy.get('[data-testid="export-format-select"]').select('csv');
    cy.get('[data-testid="export-confirm-button"]').click();

    cy.readFile('cypress/downloads/records.csv').should('exist');
    cy.readFile('cypress/downloads/records.csv').then((fileContent) => {
      expect(fileContent).to.include('id,name,email,status');
      expect(fileContent.split('\n').length).to.be.greaterThan(1);
    });

    cy.get('[data-testid="export-success-message"]').should('contain', 'Export completed successfully');
  });

  it('should export filtered records to CSV', () => {
    cy.get('[data-testid="filter-input"]').type('active');
    cy.get('[data-testid="filter-apply-button"]').click();
    cy.get('[data-testid="record-row"]').should('have.length.greaterThan', 0);

    cy.get('[data-testid="export-button"]').click();
    cy.get('[data-testid="export-format-select"]').select('csv');
    cy.get('[data-testid="export-confirm-button"]').click();

    cy.readFile('cypress/downloads/records.csv').should('exist');
    cy.readFile('cypress/downloads/records.csv').then((fileContent) => {
      const lines = fileContent.split('\n');
      expect(lines.length).to.be.greaterThan(1);
      lines.slice(1).forEach((line) => {
        if (line.trim()) {
          expect(line.toLowerCase()).to.include('active');
        }
      });
    });
  });

  it('should handle export with no records gracefully', () => {
    cy.get('[data-testid="filter-input"]').type('nonexistentrecord12345');
    cy.get('[data-testid="filter-apply-button"]').click();
    cy.get('[data-testid="record-row"]').should('have.length', 0);

    cy.get('[data-testid="export-button"]').should('be.disabled');
    cy.get('[data-testid="no-records-message"]').should('contain', 'No records to export');
  });

  it('should export with custom column selection', () => {
    cy.get('[data-testid="export-button"]').click();
    cy.get('[data-testid="export-format-select"]').select('csv');
    cy.get('[data-testid="column-select-toggle"]').click();

    cy.get('[data-testid="column-checkbox-name"]').should('be.checked');
    cy.get('[data-testid="column-checkbox-email"]').uncheck();
    cy.get('[data-testid="column-checkbox-status"]').should('be.checked');

    cy.get('[data-testid="export-confirm-button"]').click();

    cy.readFile('cypress/downloads/records.csv').should('exist');
    cy.readFile('cypress/downloads/records.csv').then((fileContent) => {
      expect(fileContent).to.include('id,name,status');
      expect(fileContent).not.to.include('email');
    });
  });

  it('should show error message when export fails', () => {
    cy.intercept('POST', '/api/export', { statusCode: 500, body: { error: 'Server error' } });

    cy.get('[data-testid="export-button"]').click();
    cy.get('[data-testid="export-format-select"]').select('csv');
    cy.get('[data-testid="export-confirm-button"]').click();

    cy.get('[data-testid="export-error-message"]').should('contain', 'Failed to export records');
    cy.get('[data-testid="export-error-message"]').should('be.visible');
  });
});
